CREATE DEFINER=`root`@`localhost` FUNCTION `fn_generar_fecha_nacimiento`(p_edad_min INT, p_edad_max INT) RETURNS date
    NO SQL
BEGIN
    DECLARE v_edad INT;
    DECLARE v_dias_extra INT;
    
    SET v_edad = fn_entero_aleatorio(p_edad_min, p_edad_max);
    SET v_dias_extra = fn_entero_aleatorio(0, 364);
    
    RETURN DATE_SUB(CURDATE(), INTERVAL (v_edad * 365 + v_dias_extra) DAY);
END ;;
